// SIMULATED SENSOR · 3 ceiling microphones (every 1 s).
// No need to edit. Each microphone reports a level in dB.
// The dashboard button "Someone coughs" makes a person
// under mic 1 cough: mic 1 jumps to about 110 dB.
const scene = flow.get('scene') || 'empty';
const mic2Broken = flow.get('mic2Broken') === true;
const people = Math.min(flow.get('peopleTrue') || 0, flow.get('peopleReported') || 0);
const TARGET = { empty: 0, conference: 150, concert: 800, intermission: 450 };

// The show starts only when the audience is seated
let phase;
if (scene === 'concert' || scene === 'conference') {
    phase = people >= 0.9 * TARGET[scene] ? 'performing' : 'arriving';
} else if (scene === 'intermission') {
    phase = 'break';
} else {
    phase = people > 0 ? 'leaving' : 'idle';
}

// Hall geometry (same numbers as the dashboard drawing)
const ROWS = 25, COLS = 32;
const seatX = r => 232 + r * 23.5;
const seatY = c => 56 + c * 12.6 + (c >= 16 ? 12 : 0);
const MIC1 = { x: seatX(5), y: seatY(8) };
function hash32(i) {
    let x = Math.imul(i + 1, 0x9E3779B1 | 0);
    x ^= x >>> 16; x = Math.imul(x, 0x85EBCA6B | 0);
    x ^= x >>> 13; x = Math.imul(x, 0xC2B2AE35 | 0);
    x ^= x >>> 16; return x >>> 0;
}
let order = context.get('order');
if (!order) {
    order = Array.from({ length: ROWS * COLS }, (_, i) => i)
        .sort((a, b) => hash32(a) - hash32(b));
    context.set('order', order);
}

const noise = a => (Math.random() * 2 - 1) * a;
const t = Date.now() / 1000;
let base;
if (phase === 'performing' && scene === 'concert') {
    const swell = 2 * Math.sin(t / 6);             // the music breathes
    base = [85 + swell, 84 + swell, 83 + swell];   // nearer the stage = louder
} else if (phase === 'performing') {
    base = [62, 60, 58];                           // one person speaking
} else if (people > 0) {
    const chatter = 46 + 18 * Math.min(1, people / 800);
    base = [chatter, chatter, chatter];            // audience talking
} else {
    base = [33, 33, 33];                           // empty: ventilation only
}
const trueLevel = (base[0] + base[1] + base[2]) / 3;
const mics = base.map(b => b + noise(1));

// "Someone coughs": the occupied seat closest to mic 1
let cough = null;
if (flow.get('coughNext')) {
    flow.set('coughNext', false);
    let seat = -1, best = Infinity;
    for (let k = 0; k < people; k++) {
        const s = order[k];
        const d = Math.hypot(seatX(Math.floor(s / COLS)) - MIC1.x, seatY(s % COLS) - MIC1.y);
        if (d < best) { best = d; seat = s; }
    }
    if (seat < 0) seat = 5 * COLS + 9;             // empty hall: a lonely visitor
    mics[0] = 110 + noise(1);
    cough = { id: Date.now(), seat: seat, mic: 0 };
}
if (mic2Broken) mics[1] = 0;                       // a broken microphone sends 0

msg.topic = 'mics';
msg.payload = mics.map(v => Math.round(v * 10) / 10);
const tick = flow.get('peopleTickAt') || Date.now();
const nextCount = Math.max(0, Math.ceil(5 - (Date.now() - tick) / 1000));
msg.sim = { scene, phase, cough, mic2Broken, trueLevel: Math.round(trueLevel), target: TARGET[scene] || 0, nextCount };
return msg;

// SIMULATED SENSOR · people counter at the doors (every 5 s).
// No need to edit.
const scene = flow.get('scene') || 'empty';
const target = { empty: 0, conference: 150, concert: 800, intermission: 450 }[scene] || 0;
let now = flow.get('peopleTrue') || 0;
// people walk in or out, at most 270 per 5 seconds
now = now + Math.max(-270, Math.min(270, target - now));
flow.set('peopleTrue', now);
flow.set('peopleReported', now);
flow.set('peopleTickAt', Date.now());
msg.topic = 'people';
msg.payload = now;
return msg;

// SIMULATED SENSOR · temperature (every 10 s). No need to edit.
const set = flow.get('tempSet');
const base = (typeof set === 'number') ? set : 20;
msg.topic = 'temperature';
msg.payload = Math.round((base + (Math.random() * 2 - 1) * 0.15) * 10) / 10;
return msg;

// DATA ALIGNMENT (ready-made)
// The sensors report at different speeds: microphones every 1 s, people every 5 s,
// temperature every 10 s. The fast data drives the clock. The slow data is HELD:
// we keep its latest value and attach it to every microphone reading.
const now = Date.now();
if (msg.topic === 'people' || msg.topic === 'temperature') {
    context.set(msg.topic, { value: msg.payload, time: now });
    return null;                       // wait for the next microphone reading
}
const people = context.get('people');
const temperature = context.get('temperature');
if (!people || !temperature) return null;   // not every sensor has reported yet

msg.payload = {
    mics: msg.payload,                 // [mic 1, mic 2, mic 3] in dB
    people: people.value,              // latest people count
    temperature: temperature.value,    // latest temperature in °C
    age: {                             // how old the held values are, in seconds
        people: (now - people.time) / 1000,
        temperature: (now - temperature.time) / 1000
    }
};
return msg;

// MISSION 1 · CLEAN
// Problem: when one person coughs next to a
// microphone, the twin thinks the whole hall is
// too loud and turns the speakers down.
//
// The AVERAGE lets the cough in.
// The MEDIAN (the middle of 3 values) ignores it.
//
// Change the line marked <-- to use median(...)
// Then click Done, then Deploy (top right).

function median(a, b, c) {
    return [a, b, c].sort((x, y) => x - y)[1];
}
const [m1, m2, m3] = msg.payload.mics;

msg.payload.level = (m1 + m2 + m3) / 3;   // <--

return msg;

// READY-MADE · the twin protects the audience's ears.
// During the show: if the hall level jumps 5 dB above
// normal, the twin turns the speakers DOWN 6 dB. If it
// drops 5 dB, it turns them UP. Then the volume slowly
// returns to normal. "Normal" = middle of the last 10 s.
const key = (msg.sim && msg.sim.scene) + '/' + (msg.sim && msg.sim.phase);
let hist = context.get('hist') || [];
let vol = context.get('vol') || 0;
if (context.get('key') !== key) { hist = []; vol = 0; context.set('key', key); }

const level = msg.payload.level;
let action = 'hold';
const show = msg.sim && msg.sim.phase === 'performing';
if (show && typeof level === 'number' && isFinite(level)) {
    if (hist.length >= 3) {
        const normal = hist.slice().sort((a, b) => a - b)[Math.floor(hist.length / 2)];
        if (level > normal + 5) action = 'down';
        else if (level < normal - 5) action = 'up';
        msg.payload.normalLevel = normal;
    }
    hist.push(level);
    if (hist.length > 10) hist.shift();
}
if (action === 'down') vol = Math.max(-12, vol - 6);
else if (action === 'up') vol = Math.min(6, vol + 6);
else vol = Math.abs(vol) < 0.3 ? 0 : vol * 0.8;   // drift back to normal

context.set('hist', hist);
context.set('vol', vol);
msg.payload.speakers = action;                    // 'hold', 'down' or 'up'
msg.payload.speakerVolume = Math.round(vol * 10) / 10;   // dB, 0 = normal
return msg;

// MISSION 2 · COMBINE (this is "data fusion")
// Problem: the people counter works, but the twin
// does not use it. It thinks the hall is empty,
// so its echo time (RT) is wrong when people come.
//
// People absorb sound (like curtains and sofas),
// so a full hall echoes less than an empty one.

// STATIC part of the twin: the room model
// (Milan hall; absorption values are assumed)
const hall = {
    volume: 7950,          // m³
    roomAbsorption: 600,   // walls, ceiling, stage
    seatArea: 500,         // m² of seats
    emptySeat: 0.60,       // sound an empty seat absorbs
    person: 0.86,          // sound a person absorbs
    seats: 800
};

// LIVE part: share of seats taken (0 to 1)
const occupied = 0;   // <-- use msg.payload.people / hall.seats

// Then click Done, then Deploy (top right).

// Sabine formula with the audience (paper, Eq. 1)
const seatAbsorption = hall.seatArea *
    (occupied * hall.person + (1 - occupied) * hall.emptySeat);
msg.payload.rt = 0.16 * hall.volume / (hall.roomAbsorption + seatAbsorption);
msg.payload.occupied = occupied;   // what the twin believes
return msg;

// MISSION 3 · ACT
// Problem: the twin knows the echo time (rt), but
// it never changes the hall. At a conference the
// hall is too echoey, so words blur together.
//
// Rule: if rt is above the target, the preset
// must become "SPEECH". Write it as an if.
const target = 1.30;        // seconds
let preset = "ORCHESTRA";

// <-- write your if here


// Then click Done, then Deploy (top right).
msg.payload.target = target;
msg.payload.preset = preset;
return msg;

// READY-MADE · delay of the back speaker.
// Sound travels faster in warm air:
//   c = 331.3 + 0.606 × T   (m/s)
// The back speaker is 34 m from the stage. It waits
// until the sound from the stage arrives, otherwise
// the audience hears an echo.
const c = 331.3 + 0.606 * msg.payload.temperature;
msg.payload.delayMs = 34 / c * 1000;
return msg;

// GAME MASTER · please do not open: the answers are inside :)
// Checks each mission by its RESULT (not by the text of the code)
// and opens the next level when the player has tested the fix.
const p = msg.payload, sim = msg.sim || {};
const num = v => typeof v === 'number' && isFinite(v);
const g = flow.get('game') || { level: 1, passed: [false, false, false, false], resetAt: 0, restartAt: 0 };
let st = context.get('st');
if (!st || st.resetAt !== g.resetAt) st = { resetAt: g.resetAt, restartAt: g.restartAt, seen: [false, false, false], low2: false, speech: false, orchestra: false };
if (st.restartAt !== g.restartAt) {             // "Restart this level": forget only this level
    st.restartAt = g.restartAt;
    if (g.level <= 3) st.seen[g.level - 1] = false;
    if (g.level === 2) st.low2 = false;
    if (g.level === 3) { st.speech = false; st.orchestra = false; }
}
const show = sim.phase === 'performing';

// Mission 1 · is the hall level the median of the 3 microphones?
// Only judge when median and average are clearly different, otherwise the old code can look right by chance.
const med = Array.isArray(p.mics) ? p.mics.slice().sort((a, b) => a - b)[1] : NaN;
const avg = Array.isArray(p.mics) ? (p.mics[0] + p.mics[1] + p.mics[2]) / 3 : NaN;
if (!num(p.level)) st.f1 = false;
else if (Math.abs(med - avg) > 0.3) st.f1 = Math.abs(p.level - med) < 0.05;
const fixed1 = st.f1 === true;
if (g.level === 1 && sim.cough && show && !fixed1 && p.speakers === 'down') st.seen[0] = true;
if (sim.cough && show && fixed1 && p.speakers === 'hold') g.passed[0] = true;

// Mission 2 · does the twin use the live people count?
const realShare = num(p.people) ? p.people / 800 : 0;
const known2 = num(p.occupied) && num(p.people) && (p.people >= 50 || p.occupied > 0);
const fixed2 = known2 && Math.abs(p.occupied - realShare) < 0.01;
if (g.level === 2 && num(p.people) && p.people >= 300 && num(p.occupied) && !fixed2) st.seen[1] = true;
if (fixed2 || (num(p.people) && p.people < 50)) {
    if (num(p.people) && p.people <= 300) st.low2 = true;          // the doors opened after the fix
    if (fixed2 && st.low2 && p.people >= 700) g.passed[1] = true;  // ...and the hall filled up
} else st.low2 = false;

// Mission 3 · does the preset follow the rule, both ways?
let fixed3 = false;
if (num(p.rt) && num(p.target) && typeof p.preset === 'string') {
    const right = p.rt > p.target ? 'SPEECH' : 'ORCHESTRA';
    // the old code always says ORCHESTRA, so only a long echo (should be SPEECH) proves the fix
    if (right === 'SPEECH') st.f3 = p.preset === 'SPEECH';
    else if (p.preset === 'SPEECH') st.f3 = false;
    fixed3 = st.f3 === true && p.preset === right;
    if (g.level === 3 && show && sim.scene === 'conference' && p.preset !== 'SPEECH') st.seen[2] = true;
    if (!fixed3) { st.speech = false; st.orchestra = false; }
    else if (show && fixed2) {
        if (right === 'SPEECH' && sim.scene === 'conference') st.speech = true;
        if (right === 'ORCHESTRA' && sim.scene === 'concert' && st.speech) st.orchestra = true;
    }
    if (st.speech && st.orchestra) g.passed[2] = true;
}

context.set('st', st);
flow.set('game', g);
msg.game = {
    level: g.level,
    passed: g.passed.slice(),
    seen: st.seen.slice(),
    fixed: [fixed1, known2 ? fixed2 : null, st.f3 === true],
    speechDone: st.speech,
    health: [num(p.level), num(p.occupied) && num(p.rt), typeof p.preset === 'string']
};
return msg;

// READY-MADE · buttons on the game page arrive here.
// They change the simulated hall and the game level.
const g = flow.get('game') || { level: 1, passed: [false, false, false, false], resetAt: 0, restartAt: 0 };
const TARGET = { empty: 0, conference: 150, concert: 800, intermission: 450 };
let out = null;

function hall(scene, people) {
    flow.set('scene', scene);
    flow.set('peopleTrue', people);
    flow.set('peopleReported', people);
    out = { topic: 'people', payload: people };   // tell the twin at once
}
// the first people count after a button comes at once, the next ones every 5 s
function firstStep() {
    const scene = flow.get('scene') || 'empty';
    const now = flow.get('peopleTrue') || 0;
    const target = TARGET[scene] || 0;
    const next = now + Math.max(-270, Math.min(270, target - now));
    flow.set('peopleTrue', next);
    flow.set('peopleReported', next);
    out = { topic: 'people', payload: next };
}
function setup(level) {
    flow.set('mic2Broken', false);
    flow.set('tempSet', 20);
    if (level === 1 || level === 4) hall('concert', 800);   // the concert is playing
    else hall('empty', 0);                                   // a new evening, doors closed
}

switch (msg.topic) {
    case 'cough': flow.set('coughNext', true); break;
    case 'doors': flow.set('scene', 'concert'); flow.set('peopleTrue', 0); firstStep(); break;
    case 'scene': flow.set('scene', String(msg.payload)); firstStep(); break;
    case 'hallNow':   // bonus round: put the hall straight into a situation
        flow.set('mic2Broken', false); flow.set('tempSet', 20);
        hall(String(msg.payload.scene || 'concert'), Number(msg.payload.people) || 0);
        break;
    case 'mic2Broken': flow.set('mic2Broken', msg.payload === true); break;
    case 'tempSet': flow.set('tempSet', Number(msg.payload)); break;
    case 'game':
        if (msg.payload === 'reset') {
            g.level = 1; g.passed = [false, false, false, false]; g.resetAt = Date.now();
            setup(1);
        } else if (msg.payload === 'restart') {
            if (g.level <= 3) g.passed[g.level - 1] = false;
            g.restartAt = Date.now();
            setup(g.level);
        } else if (msg.payload === 'next' && g.passed[g.level - 1] && g.level < 4) {
            g.level += 1;
            setup(g.level);
        } else if (msg.payload === 'start' && !flow.get('started')) {
            flow.set('started', true);
            setup(g.level);
        }
        flow.set('game', g);
        break;
}
return out;
